const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const orlando = ee.Geometry.Point(-81.3792, 28.5383).buffer(20000); // 20km buffer around Orlando
  const region = orlando.bounds();

  // Time ranges with ±1 year tolerance
  const start1973 = '1972-01-01';
  const end1973 = '1974-12-31';
  const start2014 = '2013-01-01';
  const end2014 = '2015-12-31';

  // 2. Data Acquisition - Landsat MSS for 1973
  let mssCol = ee.ImageCollection('LANDSAT/LM01/C02/T1')  // Landsat 1 MSS
    .filterBounds(region)
    .filterDate(start1973, end1973);

  // Check if empty, try Landsat 2
  if (mssCol.size().getInfo() === 0) {
    mssCol = ee.ImageCollection('LANDSAT/LM02/C02/T1')
      .filterBounds(region)
      .filterDate(start1973, end1973);
  }

  // Check if empty, try Landsat 3
  if (mssCol.size().getInfo() === 0) {
    mssCol = ee.ImageCollection('LANDSAT/LM03/C02/T1')
      .filterBounds(region)
      .filterDate(start1973, end1973);
  }

  // Check MSS collection
  const mssCount = mssCol.size().getInfo();
  console.log(`1973±1 MSS Images: ${mssCount}`);

  if (mssCount === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Get Landsat 8 for 2014
  let l8Col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(region)
    .filterDate(start2014, end2014);

  const l8Count = l8Col.size().getInfo();
  console.log(`2014±1 Landsat 8 Images: ${l8Count}`);

  if (l8Count === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Processing functions
  // Cloud masking for MSS (simple cloud score)
  function maskCloudsMSS(img) {
    // MSS has no QA band, use simple threshold on thermal band if available
    // For simplicity, we'll use a cloud score based on brightness
    const score = img.select('B4').gt(0.25); // Simple threshold on NIR
    return img.updateMask(score.not());
  }

  // Cloud masking for Landsat 8 using QA_PIXEL
  function maskCloudsL8(img) {
    const qa = img.select('QA_PIXEL');
    const cloudMask = qa.bitwiseAnd(1 << 3).or(qa.bitwiseAnd(1 << 4));
    return img.updateMask(cloudMask.eq(0));
  }

  // 5. Process 1973 MSS
  const mssComposite = mssCol
    .map(maskCloudsMSS)
    .median()
    .clip(region);

  // Calculate built-up index for MSS: (B4 - B2)/(B4 + B2) where B4=NIR, B2=Red
  const mssIndex = mssComposite.normalizedDifference(['B4', 'B2']).rename('built_index');

  // Threshold for built-up (urban areas tend to have lower vegetation)
  const mssBuilt = mssIndex.gt(-0.1); // Empirical threshold

  // 6. Process 2014 Landsat 8
  const l8Composite = l8Col
    .map(maskCloudsL8)
    .median()
    .clip(region);

  // Calculate NDBI for Landsat 8: (B6 - B5)/(B6 + B5)
  const l8Index = l8Composite.normalizedDifference(['SR_B6', 'SR_B5']).rename('built_index');

  // Threshold for built-up
  const l8Built = l8Index.gt(0); // Standard NDBI threshold

  // 7. Count built-up pixels
  const mssCountResult = mssBuilt.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9,
  }).get('built_index');

  const l8CountResult = l8Built.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9,
  }).get('built_index');

  const mssPixels = mssCountResult.getInfo();
  const l8Pixels = l8CountResult.getInfo();

  console.log(`1973 Built-up pixels: ${mssPixels}`);
  console.log(`2014 Built-up pixels: ${l8Pixels}`);

  // 8. Validation
  if (mssPixels === null || l8Pixels === null || 
      isNaN(mssPixels) || isNaN(l8Pixels)) {
    console.log("<answer>C3</answer>");
    return;
  }

  if (mssPixels === 0 || l8Pixels === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 9. Comparison
  const percentChange = ((l8Pixels - mssPixels) / mssPixels * 100).toFixed(1);
  console.log(`Change: ${percentChange}%`);

  if (l8Pixels > mssPixels) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
